import type {WardogsItem} from "./item-library";
type ItemProse = Pick<WardogsItem, "summary" | "description" | "role" | "strengths" | "cautions" | "confirmedFacts" | "unconfirmedFacts">;
type Authored = Omit<ItemProse, "confirmedFacts">;
const p = (summary: string, description: string, role: string, strengths: string[], cautions: string[], unconfirmedFacts?: string[]): Authored => ({summary, description, role, strengths, cautions, unconfirmedFacts});
const authored: Record<string, Authored> = {
  mortar: p("Средство непрямого огня против скоплений на крышах, башнях, в обороне FOB и у неподвижных целей.", "Миномёт стал первым оружейным предметом WARDOGS с отдельной страницей: записи показывают реальный интерес к этому оружию в поиске. Используйте страницу как тактическое руководство по условиям применения, противодействию и источникам, а не как окончательную таблицу характеристик.", "Превращайте сообщения союзников в огневое давление и вытесняйте противника с предсказуемых позиций.", ["Наказывает скопления игроков на крышах, башнях и очевидных подходах к цели.", "Может ослабить оборону FOB перед атакой пехоты или техники.", "Полезен отрядам, которые передают метки целей и команды коррекции."], ["Окончательные урон, время перезарядки, запас боеприпасов и условия разблокировки не подтверждены.", "Противник может атаковать расчёт, обнаружив огневую позицию.", "При плохой разведке выстрелы становятся догадками, а не надёжным огнём."]),
  "a-91": p("В Alpha 1 A-91 была винтовкой линии опыта штурмовика массой 3.17 kg, под 5.56x45mm, с одиночным огнём и очередями.", "A-91 занимала нишу контролируемых очередей в списке штурмовых винтовок Alpha 1. Цена не была записана, но калибр, два режима огня, масса и линия опыта штурмовика позволяют обсуждать осмысленное давление на простреливаемые направления, не предполагая баланс релизной версии.", "Ведите размеренный одиночный огонь вдаль и короткие очереди по цели, пересекающей оживлённый проход. До выбора основной винтовки учитывайте пока неизвестную цену покупки.", ["Одиночный огонь и очереди дают модели Alpha 1 два управляемых ритма боя.", "Наблюдаемый 5.56x45mm относится к самой широкой группе оружия каталога.", "Записанная масса 3.17 kg ниже, чем у FAL и Galil в Alpha."], ["Цена покупки в Alpha 1 не записана, поэтому полное сравнение расходов невозможно.", "Автоматический режим в записи не показан; вблизи нужны дисциплинированные очереди.", "Магазины STANAG записаны отдельно, но совместимость именно с A-91 не подтверждена."], ["Цена Alpha 1 не записана; цены раннего доступа и полной версии не подтверждены.", "Урон, отдача, совместимость модификаций и баланс могут измениться в раннем доступе или полной версии."]),
  ak74: p("В Alpha 1 AK74 была винтовкой линии опыта штурмовика массой 3 kg под 5.45x39mm, с одиночным и автоматическим огнём.", "AK74 была единственной моделью под 5.45x39mm среди записанного оружия Alpha 1. Отдельная экономика боеприпасов, переключатель одиночного и автоматического огня и масса 3 kg определяют её дорелизную роль, хотя цена продавца не была записана.", "Используйте одиночный огонь для экономии патронов и автоматический для ближнего штурма. Помните, что комплект AK74 зависит от менее распространённого снабжения 5.45x39mm.", ["Одиночный и автоматический режимы дают размеренные выстрелы и немедленное давление вблизи.", "В Alpha 1 масса 3 kg была ниже, чем у других записанных штурмовых винтовок.", "Запись 75-патронного барабана AK74 позволяет обсуждать комплект большой ёмкости."], ["Цена продавца в Alpha 1 не была записана.", "Только одно записанное оружие использовало 5.45x39mm, поэтому обмен патронами уже, чем для 5.56x45mm.", "Цена барабана на 75 патронов, влияние на обращение и окончательная доступность не записаны."], ["Цена Alpha 1 не записана; цены раннего доступа и полной версии не подтверждены.", "Цена барабана, окончательные отдача, урон и настройка прогресса для раннего доступа и полной версии не подтверждены."]),
  "amp-9": p("В Alpha 1 AMP-9 стоила $900 и была пистолетом-пулемётом линии медика под 9x19mm, с одиночным и автоматическим огнём, массой 1.4 kg.", "AMP-9 сочетала самую низкую массу огнестрельного оружия среди этих 14 записей с линией опыта медика и четырьмя записанными размерами магазина. Данные Alpha 1 показывают мобильное оружие поддержки, итоговые расходы на которое зависят от магазина и снабжения 9x19mm, а не только от цены $900.", "Берите AMP-9 как лёгкое основное оружие медика для ближней защиты: одиночный огонь экономит 9x19mm, автоматический помогает под немедленным давлением при оживлении или на цели.", ["Масса 1.4 kg в Alpha 1 оставляет больше места для медицинских средств и защиты.", "Медик может выбирать экономию патронов или ближний огонь.", "Магазины AMP-9 на 15, 20, 30 и 50 патронов дают несколько вариантов ёмкости и бюджета."], ["Цена $900 в Alpha 1 не включает патроны и сменные магазины.", "Наблюдаемый магазин на 50 патронов стоил $180 — заметная надбавка к бюджетному ПП.", "Дальность, отдача и спад урона не записаны в материалах каталога."], ["Урон, отдача, дальность и требования опыта медика могут измениться в раннем доступе или полной версии.", "Цены магазинов и совместимость Alpha 1 не подтверждены как окончательные значения."]),
  "amr-50": p("В Alpha 1 AMR 50 была снайперской винтовкой линии разведчика за $8,800, под .50 Cal, с продольно-скользящим затвором и магазином, массой 12.5 kg.", "AMR 50 находилась на крайнем конце оружейной экономики: самая дорогая и тяжёлая из этих 14 моделей. Патроны .50 Cal также были записаны по $50 за штуку и $250 за коробку, поэтому выход с ней в Alpha 1 требовал специального вложения разведчика.", "Используйте AMR 50 с подготовленной наблюдательной позиции, где цена замены, масса 12.5 kg и дорогие патроны оправданы целями, с которыми лёгкая винтовка справляется менее уверенно.", ["Калибр .50 Cal выделяет роль тяжёлой винтовки в каталоге Alpha.", "Затвор и магазин позволяют осмысленные повторные выстрелы без перезарядки после каждого патрона.", "Записанный магазин AMR 50 на 10 патронов стоил $30 и даёт конкретный вариант ёмкости."], ["Цена $8,800 в Alpha 1 подвергает риску значительную долю накопленных денег.", "Наблюдаемая масса 12.5 kg намного выше BMR-308 и штурмовых винтовок.", "Патрон .50 Cal за $50 был самым дорогим записанным до окончательной настройки баланса."], ["Урон по пехоте, взаимодействие с бронёй, покачивание прицела и обращение могут измениться в раннем доступе или полной версии.", "Цена винтовки $8,800 и стоимость .50 Cal — наблюдения Alpha 1, а не подтверждённая экономика полной версии."]),
  "bmr-308": p("В Alpha 1 BMR-308 была полуавтоматической винтовкой точного стрелка линии разведчика за $6,000, под .308 Winchester, массой 3.9 kg.", "BMR-308 давала разведчику Alpha 1 полуавтоматический промежуточный вариант между тяжёлой AMR 50 и необычным Compound Bow. Калибр .308 Winchester связывает её с FAL и общей записью магазина на 20 патронов, хотя окончательную совместимость предполагать нельзя.", "Ведите повторный точный огонь на средних и длинных прострелах. Сохраняйте деньги на .308 Winchester и избегайте ближнего расхода патронов в манере штурмовой винтовки.", ["Полуавтоматический огонь ускоряет коррекцию относительно записанного затвора AMR 50.", "Масса 3.9 kg в Alpha 1 удобнее рядом с тяжёлой снайперской записью 12.5 kg.", "Для семейства FAL и BMR-308 записан магазин на 20 патронов за $150."], ["Цена $6,000 в Alpha 1 делает замену потерянной винтовки дорогой.", "Стандартные .308 Winchester наблюдались по $4 за патрон и $40 за коробку.", "Посадка оптики, обращение с магазином, урон и эффективная дальность не записаны как финальные характеристики."], ["Совместимость оптики, отдача, урон и настройка дальности раннего доступа и полной версии не подтверждены.", "Наблюдаемые цена $6,000 и расходы на магазины Alpha могут отличаться от текущего раннего доступа и полной версии."]),
  "bushmaster-m17s": p("В Alpha 1 Bushmaster M17S отображалась за $0 как винтовка штурмовика массой 3.17 kg под 5.56x45mm, с одиночным огнём и очередями.", "Bushmaster M17S имела общий с A-91 и KH-2002 записанный профиль: 5.56x45mm, одиночный огонь и очереди, 3.17 kg. Однако продавец показывал $0. Это наблюдение Alpha 1, а не доказательство навсегда бесплатного оружия на релизе.", "Рассматривайте M17S как вариант контролируемых очередей в материалах Alpha. Используйте $0 только для исторического сравнения комплектов, пока более поздние сборки не подтвердят способ получения.", ["Отображённое значение $0 в Alpha 1 сводило записанную цену самого оружия к нулю.", "Одиночный огонь и очереди позволяют размеренные выстрелы без обязательного автоматического расхода.", "Калибр 5.56x45mm относился к самой распространённой группе каталога."], ["$0 у дорелизного продавца может означать стартовый доступ, временные данные или настройку.", "В записанных режимах не было автоматического огня.", "Отдельные записи магазинов STANAG не доказывают, что каждая ёмкость подходит M17S."], ["Отображённая цена $0 в Alpha 1 не подтверждена для раннего доступа или полной версии.", "Правила получения, урон, отдача и совместимость модификаций могут измениться в раннем доступе или полной версии."]),
  "compound-bow": p("В Alpha 1 Compound Bow стоил $800 и был оружием разведчика массой 1.3 kg со стандартными стрелами и стрельбой натяжением и отпусканием тетивы.", "Compound Bow был самым лёгким записанным оружием и единственным вариантом со стандартными стрелами и ритмом натяжения-отпускания. Цена $800 в Alpha 1 делала его дешёвым рядом с винтовками разведчика, но урон, возврат, скорость и запас стрел не записаны.", "Выбирайте лёгкий лук разведчика, если умеете выдерживать натяжение и момент выпуска. Берите пистолет для ситуаций, где обычный магазин прощает больше ошибок.", ["Масса 1.3 kg была самой низкой среди 14 записанных моделей оружия.", "Цена $800 в Alpha 1 значительно ниже BMR-308 и AMR 50.", "Стандартные стрелы дают отдельный вариант снабжения вне групп калибров огнестрельного оружия."], ["При натяжении и отпускании не наблюдался запасной одиночный или автоматический режим.", "Урон, скорость, падение, возврат и носимый запас стрел не записаны.", "В каталоге нет отдельной страницы стрел или подтверждённой матрицы модификаций."], ["Урон, скорость, возврат и ёмкость стрел для раннего доступа и полной версии не подтверждены.", "Цена $800 в Alpha и требования опыта разведчика могут отличаться от текущего раннего доступа или полной версии."]),
  deagle: p("В Alpha 1 Deagle была полуавтоматическим пистолетом под .50 AE за $900; масса и прогресс не записаны.", "Deagle стоила $900 в списке пистолетов Alpha 1 — на уровне основного оружия — и использовала редкий .50 AE. Магазин на семь патронов записан за $50, но отсутствие массы и прогресса оставляет важные вопросы о комплекте открытыми.", "Выбирайте Deagle, когда дорогой полуавтоматический резерв с малой ёмкостью подходит плану. До сравнения с дешёвыми пистолетами учитывайте .50 AE и магазины.", ["Калибр .50 AE был уникальным среди 14 записанных моделей.", "Полуавтоматический механизм не требует медленного натяжения или ручного затвора специальных видов оружия.", "Записан конкретный семипатронный магазин Deagle, позволяющий обсуждать ёмкость."], ["Цена $900 в Alpha 1 равнялась AMP-9 до покупки патронов и магазинов.", "Записанный магазин на семь патронов стоил $50 и оставляет мало места для ошибки.", "Сезон 1 подтверждает Career 85; текущие масса и полный вес комплекта остаются непроверенными."], ["В Alpha 1 масса и прогресс отсутствовали; Сезон 1 подтверждает Career 85, но масса раннего доступа и полной версии не проверена.", "Урон, отдача и поведение магазина могут отличаться от текущей сборки; цена продавца $900 в Alpha 1 не проверена для раннего доступа."]),
  fal: p("В Alpha 1 FAL была винтовкой штурмовика за $5,500, под .308 Winchester, с одиночным и автоматическим огнём, массой 4.25 kg.", "FAL была самой тяжёлой и дорогой записанной штурмовой винтовкой: вместо распространённой экономики 5.56x45mm она использовала .308 Winchester и автоматический огонь. Записанные магазины на 20 и 30 патронов также стоили дороже многих малокалиберных вариантов.", "Одиночным огнём контролируйте расход .308 Winchester; автоматический оставляйте для короткого решительного давления. В Alpha 1 и винтовка, и патроны, и магазины требовали значительных затрат.", ["Одиночный и автоматический режимы позволяют перейти от точности к ближнему давлению.", "Калибр .308 Winchester отличает её от лёгких штурмовых винтовок под 5.56x45mm.", "Записи магазинов на 20 и 30 патронов дают два конкретных варианта ёмкости."], ["Цена $5,500 в Alpha 1 намного выше записанных Galil и AMP-9.", "Масса 4.25 kg была самой высокой среди штурмовых винтовок Alpha.", "Магазин FAL на 30 патронов стоил $250, стандартный .308 — $4 за патрон."], ["Урон, отдача, контроль автоматического огня и требования опыта штурмовика могут измениться в раннем доступе или полной версии.", "Цена $5,500 и расходы на магазины — наблюдения Alpha 1, а не подтверждённые финальные значения."]),
  galil: p("В Alpha 1 Galil была винтовкой штурмовика за $2,200, массой 3.95 kg, под 5.56x45mm, с одиночным и автоматическим огнём.", "Galil занимала среднюю ценовую нишу Alpha 1: дороже и тяжелее моделей под 5.56x45mm с очередями, но дешевле FAL под .308 и с автоматическим огнём. Отдельные записи магазинов на 35 и 50 патронов дают полезный контекст ёмкости.", "Используйте Galil как универсальное основное оружие штурма: дозируйте 5.56x45mm одиночным огнём на открытой местности и переходите на автоматический при сближении отряда или зачистке обороны.", ["Одиночный и автоматический режимы дают экономию и ближний огонь.", "В Alpha записаны отдельные магазины Galil на 35 и 50 патронов.", "Цена $2,200 в Alpha 1 была намного ниже FAL при сохранении автоматического огня."], ["Масса 3.95 kg выше записанных A-91, AK74, M17S и KH-2002.", "Магазин на 50 патронов стоил $110 в Alpha 1 без патронов.", "Отдача, время перезарядки, урон и эффекты модификаций не записаны как окончательные значения."], ["Отдача, урон, совместимость модификаций и настройка опыта штурмовика раннего доступа и полной версии не подтверждены.", "Цены оружия и магазинов Alpha 1 могут отличаться от текущего раннего доступа или полной версии."]),
  "ggx-17": p("В Alpha 1 GGX 17 была полуавтоматическим пистолетом под 9x19mm; цена, масса и прогресс не записаны.", "GGX 17 представляла обычную полуавтоматическую половину записанной пары пистолетов GGX. Калибр 9x19mm связывает её с самой дешёвой наблюдаемой коробкой патронов, но три отсутствующих поля продавца не позволяют надёжно сравнить полную стоимость или вес.", "Используйте GGX 17 как размеренный резерв под 9x19mm, а не замену наблюдаемому автоматическому GGX 18. Оставляйте запас бюджета, пока поздняя сборка не подтвердит цену получения.", ["Полуавтоматический огонь помогает контролировать резервные выстрелы и экономить патроны.", "Стандартные 9x19mm наблюдались по $1 за патрон и $10 за коробку.", "Общий калибр упрощает снабжение рядом с AMP-9 и GGX 18."], ["Цена, масса и прогресс отсутствовали в записи Alpha 1.", "Записаны магазины GGX на 33 и 50 патронов, но совместимость конкретной модели не доказана.", "Урон, отдача, ёмкость и обращение отсутствуют в записи оружия."], ["Цена, масса и прогресс не записаны в Alpha 1 и не подтверждены для раннего доступа или полной версии.", "Совместимость магазинов, урон, отдача и ёмкость могут отличаться от текущего раннего доступа или полной версии."]),
  "ggx-18": p("В Alpha 1 GGX 18 была пистолетом под 9x19mm с одиночным и автоматическим огнём; цена, масса и прогресс не записаны.", "GGX 18 отличалась от GGX 17 наблюдаемым автоматическим режимом, добавляя компактную автоматическую роль пистолетам Alpha 1. Это ясно видно в записи, но без цены, массы, прогресса и проверенной совместимости магазинов оценивать релизную ценность преждевременно.", "Оставляйте одиночный режим для обычного резервного использования; автоматический применяйте при срочном ближнем давлении, когда быстрый расход 9x19mm оправдывает потерю контроля патронов.", ["Одиночный и автоматический режимы делают её более гибким записанным пистолетом GGX.", "9x19mm имел низкую наблюдаемую стандартную цену $1 за патрон и $10 за коробку.", "Общий калибр подходит плану снабжения отряда с AMP-9."], ["В Alpha 1 цена, масса и прогресс не записаны.", "Автоматический пистолет быстро расходует магазин даже при дешёвых патронах.", "Записи GGX на 33 патрона за $70 и барабана на 50 за $110 не доказывают окончательную совместимость GGX 18."], ["Цена, масса и прогресс не записаны в Alpha 1 и не подтверждены для раннего доступа или полной версии.", "Настройка автоматического огня, совместимость магазинов, отдача и урон могут отличаться от текущего раннего доступа или полной версии."]),
  judge: p("В Alpha 1 Judge была пистолетом под .45 Colt за $250; режим огня, масса и прогресс не записаны.", "Judge имела самую низкую ненулевую записанную цену оружия — $250 — и была единственной моделью под .45 Colt. Каталог патронов показал коробку за $33, но отсутствующие режим огня, масса и прогресс делают её поведение менее определённым, чем цена.", "Рассматривайте Judge как кандидата с дешёвой базовой покупкой, чей реальный ритм боя ещё нужно проверить в игре. В бюджет замены включайте относительно дорогую коробку .45 Colt.", ["Цена $250 в Alpha 1 была самой низкой ненулевой покупкой среди этих моделей.", "Калибр .45 Colt даёт отдельное снабжение пистолета.", "Наблюдалась коробка .45 Colt за $33, поэтому часть расходов на замену записана."], ["Режим огня, масса и прогресс не записаны в Alpha 1.", "Для Judge нет записи собственного магазина или ёмкости.", "Базовая цена $250 не устанавливает урон, скорость перезарядки, дальность или финальную ценность."], ["Режим огня, масса и прогресс не записаны в Alpha 1 и не подтверждены для раннего доступа или полной версии.", "Ёмкость, перезарядка, урон и цена $250 в Alpha могут отличаться от текущего раннего доступа или полной версии."]),
  "kh-2002": p("В Alpha 1 KH-2002 была винтовкой штурмовика массой 3.17 kg под 5.56x45mm, с одиночным огнём и очередями; цена не записана.", "KH-2002 завершала записанную тройку штурмовых винтовок массой 3.17 kg под 5.56x45mm с очередями. В отличие от показанных $0 у M17S, цена KH-2002 в Alpha 1 отсутствовала: даже при совпадении главных характеристик выбор нельзя свести к расходам.", "Применяйте контролируемый штурмовой огонь: одиночный на длинных прострелах и очереди в короткие окна видимости. Для различий в расходах и обращении нужны данные поздних сборок.", ["Одиночный огонь и очереди дают два управляемых способа расхода патронов.", "Масса 3.17 kg в Alpha 1 ниже Galil и FAL.", "5.56x45mm — самый общий записанный калибр, расширяющий возможности снабжения отряда."], ["Цена покупки Alpha 1 не записана.", "Запись не показывает отличия в обращении от A-91 и M17S.", "Ёмкости STANAG и оптика записаны, но совместимость KH-2002 не подтверждена."], ["Цена Alpha 1 не записана; цены раннего доступа и полной версии не подтверждены.", "Специфичные обращение, урон, отдача и совместимость модификаций могут измениться в раннем доступе или полной версии."]),
  "ah-6m-miniguns": p("В Alpha 1 AH-6M Miniguns была боевым вертолётом за $7,000, но условие покупки не удалось прочитать.", "AH-6M Miniguns — вооружённый представитель лёгкого семейства AH-6 в продавце Alpha 1. Роль боевого вертолёта и цена $7,000 отделяют её от транспортной MH-6, но непрочитанный допуск и незаписанное поведение оружия оставляют страницу руководством по роли, а не финальной таблицей.", "Используйте AH-6M для коротких атакующих заходов, затем берегите машину между боями: каждая замена расходует средства по наблюдаемой экономике Alpha.", ["Наблюдаемые $7,000 в Alpha 1 ниже AH-6R Rockets и Havoc.", "Боевая роль отличается от транспортной MH-6 с наблюдаемой свободной покупкой.", "Название Miniguns даёт понятный повод сравнить её с ракетной AH-6R до покупки."], ["Условие покупки Alpha 1 не читалось; доступность нельзя выводить только из цены.", "Урон миниганов, патроны, сведение и эффективная дальность не записаны.", "Прочность, состав экипажа, управление и противодействие остаются неизвестными."], ["Непрочитанное условие Alpha 1 не подтверждено для раннего доступа или полной версии.", "Миниганы, полёт, прочность и цена $7,000 в Alpha могут отличаться от текущего раннего доступа или полной версии."]),
  "ah-6r-rockets": p("В Alpha 1 AH-6R Rockets была ракетным вертолётом за $12,500 с непрочитанным условием доступа.", "AH-6R Rockets меняет миниганы лёгкого семейства на ракетную роль и гораздо более высокую записанную цену. $12,500 в Alpha 1 требуют более осмысленной покупки, чем AH-6M, но ракетная нагрузка, взрыв, перезарядка и условие допуска не были прочитаны достаточно для окончательных выводов.", "Оставляйте AH-6R для запланированных ударов, когда отряд может найти ценную цель и обеспечить отход. Не подвергайте дорогой вертолёт риску без координации.", ["Ракетная роль отличается от AH-6M Miniguns.", "Общее семейство позволяет прямо сравнить цену и роль с AH-6M.", "$12,500 в Alpha 1 ниже Havoc при сохранении специализированной боевой роли."], ["Условие покупки не читалось в Alpha 1.", "Количество ракет, взрывной урон, точность и пополнение не записаны.", "Высокая наблюдаемая цена замены усиливает риск неподдержанных атак."], ["Непрочитанное условие Alpha 1 не подтверждено для раннего доступа или полной версии.", "Ракетная нагрузка, урон, пополнение, управление и цена могут отличаться от текущего раннего доступа или полной версии."]),
  bobcat: p("В Alpha 1 Bobcat наблюдалась как лёгкий транспорт за $500 со свободной покупкой у продавца техники.", "Bobcat занимала самый дешёвый край записанного каталога техники. Лёгкий транспорт и свободная покупка делают её ясной точкой сравнения базовой мобильности Alpha 1, но запись не устанавливает места, груз, защиту, скорость или сохранение доступа в релизных сборках.", "Покупайте Bobcat с небольшим финансовым риском для коротких перегруппировок и возвращения, когда отряду важнее мобильность, чем оружие, броня или груз.", ["Наблюдаемая цена $500 была самой низкой среди 20 записанных моделей.", "Свободная покупка была видна в Alpha 1 без показанной линии уровня.", "Роль лёгкого транспорта фокусирует выбор на перемещении, а не боевом оснащении."], ["Свободная покупка наблюдалась лишь в Alpha 1 и не гарантирует финальный доступ.", "Места, хранение, скорость, прочность и движение по местности не записаны.", "Низкая цена продавца не доказывает низкие расходы на топливо, ремонт или замену."], ["Свободная покупка и $500 — наблюдения Alpha 1, не подтверждённые правила раннего доступа или полной версии.", "Вместимость, защита, управление, хранение и эксплуатационные расходы не подтверждены для раннего доступа или полной версии."]),
  "dune-buggy": p("В Alpha 1 Dune Buggy была быстрым транспортом за $1,500 с условием Driver 10.", "Dune Buggy — явно ориентированный на скорость наземный транспорт записанного каталога. Driver 10 и $1,500 в Alpha 1 ставят её выше стартовой мобильности Bobcat, но слово быстрый — роль продавца, а не доказательство финальной скорости, ускорения, сцепления или устойчивости к авариям.", "Выбирайте Dune Buggy для быстрой разведки и смены маршрутов, когда время важнее защиты. Не рассчитывайте на непроверенное число пассажиров или грузовую ёмкость.", ["Быстрый транспорт — явное название роли в Alpha 1.", "$1,500 оставляли её дешевле крупных семейств Kodiak и Humvee.", "Driver 10 делал наблюдаемое условие прогресса читаемым, а не неизвестным."], ["Финальные скорость, ускорение, сцепление и опрокидывание не записаны.", "Сезон 1 указывает Driver 8; Driver 10 в Alpha 1 — историческое условие.", "Защита, места и грузовая спецификация не записаны."], ["Сезон 1 указывает $25,000 за разблокировку линии Driver; покупка машины за $1,500 в Alpha 1 не проверена для раннего доступа.", "Скорость, управление, прочность, места и грузовое поведение могут отличаться от текущего раннего доступа или полной версии."]),
  "flakpanzer-gepard": p("В Alpha 1 Flakpanzer Gepard была противовоздушной бронетехникой за $8,000 при Wardog 45.", "Gepard — специализированная противовоздушная бронированная модель записанного списка, с условием Wardog и ценой ниже L2A6 и SPH-2. Роль допускает применение для ограничения авиации, но обнаружение, работа пушек, броня, экипаж и эффективная зона прикрытия не записаны как финальные системы.", "Размещайте Gepard для защиты ценных наземных объектов и вероятных воздушных подходов, оставляя наземную поддержку рядом: противовоздушная роль не означает безопасность от всех угроз.", ["Противовоздушная бронетехника была уникальной ролью среди 20 наблюдаемых машин.", "$8,000 в Alpha 1 ниже двух других тяжёлых единиц линии Wardog.", "Wardog 45 давал читаемую цель прогресса у записанного продавца."], ["Дальность обнаружения, патроны, урон пушек, возвышение и сопровождение целей не записаны.", "Противовоздушная роль не устанавливает защиту от танков, артиллерии или пехоты.", "Wardog 45 и $8,000 — только дорелизные наблюдения."], ["Wardog 45 и $8,000 не подтверждены для раннего доступа или полной версии.", "Броня, обнаружение авиации, оружие, экипаж и боеприпасы могут отличаться от текущего раннего доступа или полной версии."]),
  havoc: p("Цена Havoc $18,000 относится только к Alpha; пилот Сезона 1 сообщает о более дорогом оснащённом вылете и сильной ПВО.", "Havoc стояла на вершине наблюдаемого списка цен техники и имела широкую роль ударного вертолёта, а не оружейное имя AH-6. Это самая тяжёлая воздушная финансовая ставка в снимке Alpha 1, но оснащение, броня, размещение экипажа и допуск недоступны для окончательного сравнения.", "Вкладывайтесь в Havoc, только когда команда может поддержать дорогой ударный вертолёт разведданными, контролем воздушной обстановки и маршрутом отхода от концентрированного ответного огня.", ["Ударный вертолёт — явная роль Alpha 1, отличная от транспорта.", "$18,000 отмечают самый ясный вариант крупного вложения в авиацию у наблюдаемого продавца.", "Роль позволяет сравнить её с дешёвыми ударными AH-6M и AH-6R."], ["Условие покупки не читалось, поэтому путь получения не записан.", "Оружие, броня, датчики, противодействие и требования экипажа не записаны.", "Недавние цены и требования пилота — сообщение одного игрока, не официальный прайс.", "Согласованная ПВО может остановить дорогой самолёт или вертолёт; оцените маршрут до траты денег."], ["Непрочитанное условие Alpha 1 не подтверждено для раннего доступа или полной версии.", "Пилот Сезона 1 20 сентября сообщил Pilot 35 и примерно $22,000–$30,000 за оснащённый вылет; это непроверенное наблюдение сообщества.", "Оснащение, броня, экипаж, полётная модель, противодействие и текущая цена требуют проверки в текущем клиенте."]),
  "humvee-m249": p("В Alpha 1 Humvee M249 сочетала вооружённый транспорт, цену $3,750 и условие Driver 25.", "Humvee M249 добавляет именованное оружие поддержки к защищённой платформе Humvee без достижения записанной цены варианта Minigun. Driver 25 был намного позже Kodiak M249: два вооружённых транспорта за $3,750 представляли разные решения прогресса, хотя оружие и установка не были записаны.", "Перевозите небольшую группу с защитной огневой ролью пассажира или стрелка. Планируйте маршруты без зависимости от неподтверждённой защиты установки и салона.", ["Наблюдаемая роль вооружённого транспорта сочетает движение и установку M249.", "$3,750 в Alpha 1 были на $750 выше невооружённой Humvee и ниже Minigun.", "Driver 25 ясно отличался от Driver 8 у Kodiak M249."], ["Патроны M249, поворот, защита, точность и открытость стрелка не записаны.", "Driver 25 — наблюдение Alpha 1, не окончательное требование разблокировки.", "Места, защита салона, груз и ремонт остаются неизвестными."], ["Driver 25 и $3,750 не подтверждены для раннего доступа или полной версии.", "Поведение M249, защита, места, грузовая ёмкость и управление могут отличаться от текущего раннего доступа или полной версии."]),
  "humvee-minigun": p("В Alpha 1 Humvee Minigun была тяжёлым вооружённым транспортом за $4,500, с непрочитанным допуском в записи продавца.", "Humvee Minigun была самой дорогой записанной Humvee и единственной с ролью тяжёлого вооружённого транспорта. Доплата $1,500 к базе показывает отдельный уровень покупки Alpha 1, но неизвестный допуск и оружейные данные не позволяют заявлять скорострельность, снабжение, броню или ценность относительно M249.", "Считайте Humvee Minigun мобильной тяжёлой огневой платформой, которой нужны защищённый маршрут, согласованный стрелок и план выхода, а не непроверенной фронтовой бронетехникой.", ["Тяжёлый вооружённый транспорт — отдельная наблюдаемая роль семейства Humvee.", "Название Minigun отделяет оружейное назначение от более дешёвой M249.", "$4,500 в Alpha 1 были ниже крупной вооружённой Ural Defender M249."], ["Условие Alpha 1 не читалось, оставляя путь доступа неизвестным.", "Патроны минигана, раскрутка, поворот, урон и открытость стрелка не записаны.", "Тяжёлый вооружённый транспорт — роль, не подтверждение танковой защиты."], ["Непрочитанное условие Alpha 1 не подтверждено для раннего доступа или полной версии.", "Миниган, защита машины, вместимость, управление и цена могут отличаться от текущего раннего доступа или полной версии."]),
  humvee: p("В Alpha 1 базовая Humvee была защищённым транспортом за $3,000 с разблокировкой Driver 15.", "Невооружённая Humvee задавала основу защищённого транспорта семейства в Alpha 1. Она стоила как грузовая Kodiak Pickup и дешевле двух вооружённых Humvee, но защищённый — класс: порог брони, схема мест, предел хранения и сравнение живучести не записаны.", "Используйте базовую Humvee для защищённой перевозки людей и перемещений по оспариваемым дорогам, когда установленное оружие менее важно, чем цена ниже вооружённых вариантов.", ["Защищённый транспорт — явная роль Alpha 1, не вывод о значении брони.", "$3,000 ниже двух вооружённых вариантов Humvee.", "Driver 15 помещал её между Dune Buggy и Humvee M249 в записанной линии Driver."], ["Броня, модель урона, места и грузовой предел не записаны.", "Защищённый транспорт не гарантирует безопасность от мин, тяжёлого оружия или засад.", "Driver 15 и $3,000 могут измениться после Alpha 1."], ["Driver 15 и $3,000 не подтверждены для раннего доступа или полной версии.", "Защита, места, хранение, мобильность, топливо и ремонт могут отличаться от текущего раннего доступа или полной версии."]),
  "kodiak-m249": p("В Alpha 1 Kodiak M249 была вооружённым транспортом за $3,750 с условием Driver 8.", "Kodiak M249 была самой ранней вооружённой машиной с читаемым допуском Driver в каталоге. Она делила цену $3,750 и роль Humvee M249, но появлялась на Driver 8 вместо 25: выбор шасси и момента прогресса — разные вопросы даже до неизвестных управления, защиты и установки.", "Выбирайте Kodiak M249 для раннего отряда линии Driver, которому нужна мобильная оружейная поддержка без перехода к защищённому семейству Ural Defender; характеристики шасси остаются неподтверждёнными.", ["Driver 8 был самым низким наблюдаемым уровнем среди вооружённых наземных машин.", "Вооружённый транспорт объединяет утилитарное семейство Kodiak с установкой M249.", "$3,750 в Alpha 1 равнялись поздней Humvee M249, позволяя прямо сравнить прогресс."], ["Патроны оружия, поворот, защита и открытость стрелка не записаны.", "Driver 8 не доказывает, что модель останется ранней разблокировкой.", "Места, компромисс груза, управление, прочность и ремонт не записаны."], ["Driver 8 и $3,750 не подтверждены для раннего доступа или полной версии.", "M249, места, груз, защита, управление и прочность могут отличаться от текущего раннего доступа или полной версии."]),
  "kodiak-pickup": p("В Alpha 1 Kodiak Pickup была грузовым транспортом за $3,000 после разблокировки за $15,000.", "Kodiak Pickup — единственная записанная машина, явно названная грузовым транспортом. Продавец показывал покупку $3,000 и отдельную разблокировку $15,000, формируя двухступенчатые затраты Alpha 1 вместо уровня; объём груза, погрузка и постоянство разблокировки не записаны.", "Используйте Kodiak Pickup для снабжения, где грузовая роль важнее меньшей наблюдаемой цены базовой Kodiak или оружия варианта M249.", ["Грузовой транспорт — уникальная роль наблюдаемого списка техники.", "$3,000 в Alpha 1 равнялись базовой Humvee при другом логистическом назначении.", "Отдельные $15,000 за разблокировку читались, позволяя явно обсуждать полную наблюдаемую цену входа."], ["Не описано, была ли разблокировка за $15,000 постоянной, повторной или привязанной к аккаунту.", "Грузовые места, погрузка, ограничения предметов и потеря не записаны.", "Защита, места, скорость, управление на местности и топливо не записаны."], ["Разблокировка $15,000 и покупка $3,000 не подтверждены для раннего доступа или полной версии.", "Постоянство разблокировки, правила груза, вместимость, места, защита и управление могут отличаться от текущего раннего доступа или полной версии."]),
  kodiak: p("В Alpha 1 базовая Kodiak была утилитарным транспортом за $2,500 со свободной покупкой.", "Базовая Kodiak находилась между Bobcat и специальными Kodiak у наблюдаемого продавца. Утилитарная роль и свободная покупка делают её общим вариантом семейства Alpha 1, но точная польза — пассажирское пространство, хранение, буксировка или бездорожье — не определена записью.", "Используйте Kodiak для обычного перемещения, когда отряду не нужны явная грузовая роль Pickup или M249. Практическую вместимость проверяйте в текущей сборке.", ["Свободная покупка наблюдалась в Alpha 1 без указанной линии Driver или денежной разблокировки.", "$2,500 были дешевле обоих специальных вариантов Kodiak.", "Утилитарный транспорт даёт более широкую наблюдаемую роль, чем скоростная Dune Buggy."], ["Свободная покупка — состояние Alpha 1, которое может не сохраниться.", "Утилитарный ярлык не задаёт места, груз, буксировку, защиту или проходимость.", "Различия базовой модели и Pickup кроме роли и цены не записаны."], ["Свободная покупка и $2,500 не подтверждены как правила раннего доступа или полной версии.", "Места, груз, буксировка, защита, управление, топливо и ремонт не подтверждены для раннего доступа или полной версии."]),
  l2a6: p("В каталоге Alpha 1 L2A6 была основным боевым танком за $14,000 с условием Wardog 35.", "L2A6 имела единственный ярлык основного боевого танка и вторую по величине записанную цену техники. Wardog 35 наступал раньше Gepard и SPH-2, но Alpha 1 не устанавливает зоны брони, вооружение, места экипажа, боеприпасы, мобильность или поддержку, нужную для сохранения боеспособности.", "Используйте L2A6 как тяжёлое средство давления на открытые направления с поддержкой команды, пехотной разведкой и логистикой. Название основного боевого танка не устраняет риск позиции.", ["Основной боевой танк был уникальным наблюдаемым классом каталога из 20 моделей.", "Wardog 35 был самым ранним читаемым допуском среди трёх бронетанковых и артиллерийских записей.", "$14,000 в Alpha 1 явно отделяли его от транспорта и лёгкой противовоздушной брони."], ["Броня, слабые места, оружие, патроны, число экипажа и ремонт не записаны.", "Роль танка не доказывает неуязвимость к пехоте, авиации или артиллерии.", "Wardog 35 и покупка $14,000 не являются финальными утверждениями о прогрессе или экономике."], ["Wardog 35 и $14,000 не подтверждены для раннего доступа или полной версии.", "Броня, вооружение, боеприпасы, экипаж, мобильность, топливо и ремонт могут отличаться от текущего раннего доступа или полной версии."]),
  "mh-6": p("В Alpha 1 MH-6 была лёгким воздушным транспортом за $6,250 с наблюдаемой свободной покупкой.", "MH-6 — самый дешёвый вертолёт записанного каталога и единственный летательный аппарат с транспортной ролью и свободной покупкой. Это небоевое сравнение семейства AH-6, но места пассажиров, посадка, нагрузка, живучесть и требования пилота вне допуска продавца не записаны.", "Используйте MH-6 для лёгкой высадки, подбора и быстрой смены позиции, когда транспорт важнее установленного оружия. Выбирайте безопасные посадки и маршруты возврата.", ["Цена $6,250 в Alpha 1 была самой низкой среди наблюдаемой авиации.", "Свободная покупка читалась у продавца вместо неизвестного или уровневого условия.", "Лёгкий воздушный транспорт даёт отдельную мобильную роль рядом с вооружёнными AH-6."], ["Свободная покупка наблюдалась только в Alpha 1 и не гарантирует финальную доступность.", "Места, открытость пассажиров, полёт, прочность и допустимые ошибки посадки не записаны.", "Транспортный ярлык не устанавливает грузовую способность или невооружённый финальный комплект."], ["Свободная покупка и $6,250 не подтверждены как правила раннего доступа или полной версии.", "Места, комплект, полёт, прочность, груз и требования пилота не подтверждены для раннего доступа или полной версии."]),
  "sph-2": p("Сезон 1 перенёс категорию Artillery Tank на Career 90 с разблокировкой $500,000; цены SPH-2 у продавца и работа экипажа остаются наблюдениями конкретных сборок.", "SPH-2 была единственной самоходной артиллерией записанного продавца с условием Wardog 55. Более поздние записи Closed Beta показывают три места экипажа, стабилизацию, установку непрямой дальности, 155 mm и ручную перезарядку. Alpha показывала покупку $10,000, а позднее руководство автора — повторную покупку $8,000 после отдельных $400,000 за разблокировку. Конфликт сохранён как данные сборок, а не сведён к итоговой цене.", "Используйте SPH-2 как согласованную артиллерию, зависимую от разведки, защищённой позиции и логистики. Меняйте место, когда оно становится предсказуемым.", ["Стабилизация сохраняет пригодный прицел для повторных поправок непрямого огня.", "Наблюдаемые места разделяют водителя, главное орудие 155 mm и верхнюю защиту.", "Правильно выполненная последовательность ручной перезарядки сокращает задержку."], ["Водитель не стреляет на ходу; одиночному оператору нужно остановиться и сменить место.", "Предсказуемая позиция уязвима для дронов, авиации, контрбатарейного огня и охотящейся пехоты.", "Сезон 1 подтверждает допуск категории Artillery Tank, а не текущую цену SPH-2. Проверяйте цену, дальность и снаряды в текущей сборке."], ["Покупка $10,000 в Alpha и повторная $8,000 в Beta конфликтуют; ни одна не подтверждена для раннего доступа.", "Один игрок Сезона 1 сообщает $8,000 за повторную покупку и $11,000–$13,000 за оснащённый выход; в текущем продавце это независимо не проверено.", "Официальные изменения называют Artillery Tank, не SPH-2. Текущую модель и повторную цену нужно проверить в текущем клиенте.", "Дальность, взрыв, броня и расходы на боеприпасы требуют текущего клиента."]),
  "uh-1y-miniguns": p("В Alpha 1 UH-1Y Miniguns была вооружённым многоцелевым вертолётом за $8,000 с непрочитанным условием.", "UH-1Y Miniguns добавляет вооружённую многоцелевую роль крупному семейству UH-1Y всего за $600 сверх записанной базовой цены транспорта. Небольшой разрыв Alpha 1 делает неизвестный допуск особенно важным: без доступа, оружия, мест и нагрузки нельзя считать вооружённый вариант лучшим транспортом во всём.", "Используйте UH-1Y Miniguns на маршрутах высадки и эвакуации с сопровождением, где важен бортовой прикрывающий огонь. Сохраняйте транспортную задачу вместо погони за непроверенным уроном.", ["Вооружённый многоцелевой вертолёт сочетает транспортное семейство с именованным оснащением.", "Наблюдаемые $8,000 были только на $600 выше базовой UH-1Y.", "Пара семейства даёт ясное сравнение вооружённой и транспортной покупки."], ["Допуск Alpha 1 не читался, поэтому доступ нельзя прямо сравнить с условием Pilot базовой модели.", "Число миниганов, сектора, патроны, урон и открытость стрелка не записаны.", "Пассажирская вместимость, груз, прочность и отличия управления неизвестны."], ["Непрочитанное условие Alpha 1 не подтверждено для раннего доступа или полной версии.", "Миниганы, места, нагрузка, прочность, полёт и цена могут отличаться от текущего раннего доступа или полной версии."]),
  "uh-1y": p("В Alpha 1 базовая UH-1Y была воздушным транспортом за $7,400 с условием Pilot 10.", "Базовая UH-1Y — транспорт с ограничением прогресса в записанном каталоге, дороже свободно покупаемой MH-6 и немного дешевле вооружённой UH-1Y Miniguns. Pilot 10 читался в Alpha 1, но места, груз, полётные качества, защита и точные отличия вооружённого варианта не документированы.", "Используйте UH-1Y для планового перемещения отряда и повторной воздушной логистики после наблюдаемого допуска Pilot. Выбирайте посадки ради безопасности транспорта, а не из-за отсутствия оружейного имени.", ["Воздушный транспорт — явная роль Alpha 1, отличная от лёгких и вооружённых классов.", "Pilot 10 был единственным читаемым условием линии Pilot в записанном наборе техники.", "$7,400 располагались между MH-6 и UH-1Y Miniguns для сравнения семейства."], ["Pilot 10 и $7,400 не подтверждены как окончательные правила доступа.", "Места пассажиров, груз, модель полёта, прочность и противодействие не записаны.", "Воздушный транспорт не доказывает отсутствие оружия или защиту в поздних сборках."], ["Pilot 10 и $7,400 не подтверждены для раннего доступа или полной версии.", "Места, груз, комплект, защита, полёт и противодействие могут отличаться от текущего раннего доступа или полной версии."]),
  "ural-defender-m249": p("В Alpha 1 Ural Defender M249 была вооружённой логистикой за $6,750 с условием Driver 40.", "Ural Defender M249 была вершиной записанного семейства Ural: вооружённая логистика, Driver 40 и цена $6,750 в Alpha 1. Она добавляет именованное оружие к защищённой концепции Defender, но запись не устанавливает, сколько груза, защиты или мобильности отдано за M249.", "Сопровождайте ценные поставки бортовой защитой Ural Defender M249. Ставьте безопасность маршрута и разгрузку выше неподдержанных боевых обходов.", ["Вооружённая логистика — уникальная роль среди наблюдаемых машин.", "M249 отделяет модель от базовой Ural и защищённой Defender.", "Driver 40 и $6,750 делают записанные этапы прогресса и покупки читаемыми."], ["Патроны M249, сектора, защита, точность и открытость стрелка не записаны.", "Грузовая ёмкость и компромисс места снабжения с вооружением неизвестны.", "Driver 40 и $6,750 могут измениться после Alpha 1."], ["Driver 40 и $6,750 не подтверждены для раннего доступа или полной версии.", "Оружие, груз, защита, места, мобильность и эксплуатационные расходы могут отличаться от текущего раннего доступа или полной версии."]),
  "ural-defender": p("В Alpha 1 Ural Defender была защищённой логистикой за $6,000 при Driver 30.", "Ural Defender добавляет защищённую логистику между базовым грузовиком и вооружённой M249. Driver 30 и $6,000 читались в Alpha 1, но защищённый — не измерение брони; запись не определяет объём груза, места пассажиров, движение по маршрутам или прирост защиты над Ural.", "Выбирайте Ural Defender для более опасных поставок, когда наблюдаемая защищённая логистика важнее дешёвой покупки базовой Ural или прикрывающего оружия вооружённой модели.", ["Защищённая логистика — отдельная наблюдаемая роль, не общий транспорт.", "$6,000 в Alpha 1 помещали её точно между Ural и Ural Defender M249.", "Driver 30 давал читаемый этап прогресса среднего варианта Ural."], ["Рейтинг брони, модель урона, грузовая ёмкость и число мест не записаны.", "Защищённая логистика не подтверждает защиту от любой засады или оружия.", "Driver 30 и $6,000 остаются дорелизными наблюдениями."], ["Driver 30 и $6,000 не подтверждены для раннего доступа или полной версии.", "Защита, груз, места, управление, топливо, ремонт и потери могут отличаться от текущего раннего доступа или полной версии."]),
  ural: p("В Alpha 1 базовая Ural была логистическим грузовиком за $5,000 после разблокировки за $60,000.", "Базовая Ural задавала специализированное семейство логистики с покупкой $5,000 и самой большой видимой денежной разблокировкой записанного каталога техники. Отдельные $60,000 в Alpha 1 преобладают во входных расходах, но запись не объясняет постоянство допуска и не измеряет груз, пассажиров, защиту, скорость или снабжение.", "Используйте Ural для плановых массовых поставок и повторного снабжения после учёта обоих наблюдаемых слоёв затрат. Сопровождение и дисциплина маршрута компенсируют незаписанную защиту.", ["Логистический грузовик — явная роль Alpha 1, отдельная от обычного транспорта людей.", "Покупка $5,000 ниже двух вариантов Ural Defender.", "Разблокировка $60,000 читалась, показывая второй важный расход вместо сокрытия за уровнем."], ["Сезон 1 указывает Driver 3 и разблокировку линии Driver за $35,000 отдельно от повторной покупки машины.", "Грузовая ёмкость, загрузка, типы снабжения, пассажиры и потери не записаны.", "Защита, управление, топливо, ремонт и бездорожье не записаны."], ["Покупка машины $5,000 в Alpha 1 не проверена для раннего доступа; разблокировка $60,000 в Alpha 1 историческая.", "Постоянство допуска, груз, снабжение, защита, места и управление могут отличаться от текущего раннего доступа или полной версии."]),
  stingray: p("Stingray — наземно запускаемый противотранспортный дрон из записей Beta; текущие цена, разблокировка и урон не проверены.", "Stingray — пусковая установка и контроллер одноразового противотранспортного дрона, не обычная управляемая машина. Запись строительства Closed Beta показывает трубу и ручной контроллер. Сентябрьский ролик демонстрирует удары по технике и артиллерии, но ни один источник не устанавливает текущую магазинную цену, допуск, урон или гарантированное уничтожение.", "До пуска выберите подтверждённую ценную машину или неподвижную артиллерию, укройте оператора и поставьте товарища следить за пусковой точкой. Старый разбор полёта рекомендует управляемые финальные поправки вместо расхода всего ускорения на подходе; перепроверьте управление в текущей сборке.", ["Удалённая противотранспортная атака давит на известную неподвижную артиллерию или позицию поддержки появления.", "Пусковое оборудование и контроллер прямо видны в цитируемой строительной записи Beta.", "Сентябрьский ролик даёт более новый пример Stingray против техники."], ["Оператор может быть открыт при управлении дроном; запускайте из укрытия, не с открытой FOB.", "Не считайте полёт, наведение или урон Beta совпадающими с текущей сборкой.", "Текущие покупка, допуск, развёртывание и урон независимо не проверены."], ["Нет текущего снимка магазина или официальной заметки, подтверждающей цену, допуск, стоимость развёртывания или урон.", "Метод полёта Beta может отличаться от текущих управления и наведения."]),
};
